//! The VEX and EVEX opcodes the reference tool knows, from its output on authored bytes
//! (generated once: every opcode of every map the escapes allow, for each prefix class, operand
//! width bit and vector length, with each of the eight register and the eight memory ModRM
//! reg fields, 32 bytes per slot).
//!
//! A key is `((((((kind * 8 + map) * 4 + pp) * 2 + w) * 8 + ll) * 2 + vv) * 256) + opcode` with
//! `kind` 0 for the two-byte VEX escape (`w` is 0), 1 for the three-byte one and 2 for EVEX, `ll`
//! the vector length field (EVEX: twice the field plus the broadcast or rounding bit) and `vv` 1 when the `vvvv` field is not the unused value. The value is
//! `0x10` for an opcode the tool knows, `0x08` when some reg field has a register form, `0x04`
//! when some has a memory form and the low two bits count its immediate bytes; bits 8 to 15 say
//! which ModRM reg fields the opcode has. Opcodes that are
//! not listed are undefined to the tool.

